    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Homestay da LSI: as famílias são selecionadas pelos Accommodation Officers da própria escola e visitadas com regularidade. Você pode escolher quarto individual (ou twin, quando duas pessoas reservam para o mesmo período) com café da manhã ou meia pensão. Roupa de cama e toalhas são fornecidas e trocadas semanalmente e o anfitrião oferece pelo menos uma lavagem de roupa por semana sem custo. Quem reserva só com café da manhã normalmente não tem acesso à cozinha. Há a opção Executive, com banheiro privativo (ensuite ou de uso exclusivo), mediante suplemento. Em Londres, as casas têm boas conexões de transporte e o trajeto até a LSI London Central pode chegar a 60 minutos; as chegadas acontecem entre 7h e 23h, aos sábados ou domingos. Menores de 18 anos precisam reservar meia pensão. Nesta opção você fica em quarto individual, com banheiro compartilhado com os demais moradores. O regime inclui café da manhã; almoço e jantar ficam por sua conta.</p><p>Suplementos e condições: Suplemento de alta temporada: GBP 45/semana (14/jun a 23/ago); Suplemento dieta especial: GBP 35/semana; Outro suplemento: GBP 55.</p><p>Suplementos da casa de família em LSI London Central, por pessoa por semana: verão de 14/jun a 23/ago £45; Natal (fins de semana de 26-27/dez e 2-3/jan) £55; dieta especial £35 com café da manhã e £50 com meia pensão; quarto executivo com banheiro privativo £90; família a até 45 min da escola £40; menores de 18 anos £20. Taxa de colocação da acomodação não cobrada. Taxa de inscrição da escola £95, envio de documentos por courier £95, seguro-saúde £14 por semana, transfer do aeroporto £135 somente ida (Heathrow/London City) ou £165 (Gatwick/Stansted/Luton). Chegadas e saídas de sábado a sábado ou de domingo a domingo. Os preços da acomodação podem mudar ao longo do ano — confirme com a LSI London Central na hora da reserva. Fonte: LSI Prices and Dates 2026.</p>','["Famílias Selecionadas e Visitadas pela Escola", "Roupa de Cama e Toalhas Trocadas Semanalmente", "1 Lavagem de Roupa por Semana Inclusa", "Quarto Individual ou Twin", "Imersão Cultural", "Prática Diária de Inglês", "Opção Executive com Banheiro Privativo", "Chegadas aos Sábados ou Domingos", "Quarto Individual", "Banheiro Compartilhado", "Café da Manhã Incluso", "Ideal para quem quer imersão cultural e prática diária de inglês", "Ideal para quem prefere ter refeições resolvidas em casa", "Ideal para quem viaja sozinho e quer apoio de anfitriões locais", "Ideal para quem busca bom custo-benefício com serviços inclusos", "Ideal para quem quer privacidade no quarto pagando menos que uma suíte", "Ideal para quem não se incomoda em dividir o banheiro", "Ideal para quem quer começar o dia com refeição garantida e ter liberdade nas demais"]'::jsonb,'["Menos indicado para quem quer cozinhar livremente (sobretudo no regime só com café da manhã)", "Menos indicado para quem precisa morar a poucos minutos da escola", "Menos indicado para quem quer liberdade total de horários e visitas", "Menos indicado para quem prefere a vida social de uma residência estudantil", "Menos indicado para quem faz questão de banheiro exclusivo", "Menos indicado para quem tem horários muito rígidos de banho e rotina", "Menos indicado para quem quer todas as refeições resolvidas sem gastar fora"]'::jsonb);
